def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        if i == n:
            # End of line
            fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows
                        if i == n or line[i] == ',':
                            fields.append(''.join(field))
                            if i < n:
                                i += 1  # Skip the comma
                            break
                        else:
                            # Invalid: something other than comma or EOL after closing quote
                            return None
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without finding closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field cannot contain quotes
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))
            if i < n:
                i += 1  # Skip the comma

    return fields

